// ETFs carry no company fundamentals.
const ctx = $input.first().json;
return ctx.tickers.filter(t => !(ctx.benchmarks || []).includes(t)).map(t => ({ json: { ticker: t, run_id: ctx.run_id } }));

// One full response per ticker. Percent fields become fractions; market cap arrives in millions.
const ctx = $('When called').first().json;
const reqs = $('One item per ticker').all();
const num = (v) => (v == null || v === '' || !isFinite(Number(v)) ? null : Number(v));
const frac = (v) => { const n = num(v); return n == null ? null : n / 100; };
const rows = [], usage = [];
$input.all().forEach((it, i) => {
  const pi = Array.isArray(it.pairedItem) ? it.pairedItem[0] : it.pairedItem;
  const idx = (pi != null && typeof pi === 'object' ? pi.item : pi) ?? i;
  const ticker = reqs[idx] ? reqs[idx].json.ticker : null;
  const code = Number(it.json.statusCode) || null;
  let body = it.json.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const m = body && body.metric && typeof body.metric === 'object' ? body.metric : null;
  const ok = code === 200 && !!m && !!ticker;
  usage.push({ ticker, status: ok ? 'ok' : (code === 429 ? 'quota_skip' : 'error'), http_code: code });
  if (!ok) return;
  const evfcf = num(m['currentEv/freeCashFlowTTM']);
  rows.push({
    ticker, as_of: ctx.as_of,
    market_cap: num(m.marketCapitalization) == null ? null : Math.round(num(m.marketCapitalization) * 1e6),
    pe: num(m.peTTM), ps: num(m.psTTM), pb: num(m.pb), ev_ebitda: num(m.evEbitdaTTM),
    fcf_yield: evfcf ? Math.round(1e4 / evfcf) / 1e4 : null,
    rev_growth_yoy: frac(m.revenueGrowthTTMYoy), rev_growth_q_yoy: frac(m.revenueGrowthQuarterlyYoy), eps_growth_yoy: frac(m.epsGrowthTTMYoy),
    gross_margin: frac(m.grossMarginTTM), op_margin: frac(m.operatingMarginTTM), net_margin: frac(m.netProfitMarginTTM), roe: frac(m.roeTTM),
    debt_equity: num(m['totalDebt/totalEquityQuarterly']), current_ratio: num(m.currentRatioQuarterly), beta: num(m.beta),
    avg_vol_10d: num(m['10DayAverageTradingVolume']) == null ? null : Math.round(num(m['10DayAverageTradingVolume']) * 1e6),
    raw: m,
  });
});
const failed = usage.filter(u => u.status !== 'ok');
return [{ json: { run_id: ctx.run_id, as_of: ctx.as_of, rows, count: rows.length, usage, calls: usage.length, failed: failed.length, failed_tickers: failed.map(u => u.ticker) } }];
